    [5029]={name="Talisman of the Naga Lord",quality=2,ilvl=47,reqLevel=42,sourceType="rare_npc",instructions="Drops from Lord Sakrasis.",zone="Stranglethorn Vale",npc="Lord Sakrasis"},
