    [10043]={name="Pious Legwraps",quality=2,ilvl=31,reqLevel=13,sourceType="quest_reward",instructions="Reward from the quest 'The Tower of Althalaxx'. Pick it over the other reward choices. Starts with Balthule Shadowstrike in Ashenvale. Objective: Talk to Delgren the Purifier at Maestra's Post.",zone="Darkshore",questName="The Tower of Althalaxx",lore="For all the work that you have done, you deserve to be well rewarded. Return to Delgren and tell him that Athrikus Narassin lies stilled by your hand, and the Cult of the Dark Strand is beaten and scattered."},
